/**
 * Utility functions for managing leaderboard data and test users
 */

// Function to generate and save a test user with realistic data
export const createTestUser = (userData) => {
  if (!userData || !userData.email) {
    console.error("Invalid user data provided");
    return false;
  }
  
  // Generate random study sessions for the past 30 days
  const generateStudySessions = () => {
    const sessions = [];
    const now = new Date();
    
    // Generate between 15-30 sessions over the past month
    const sessionCount = Math.floor(Math.random() * 15) + 15;
    
    for (let i = 0; i < sessionCount; i++) {
      // Random date in past 30 days
      const sessionDate = new Date();
      sessionDate.setDate(now.getDate() - Math.floor(Math.random() * 30));
      
      // Random duration between 30 and 120 minutes
      const duration = Math.floor(Math.random() * 90) + 30;
      
      // Random subject
      const subjects = ['Mathematics', 'Physics', 'Computer Science', 'Biology', 'Chemistry', 'History', 'Literature'];
      const subject = subjects[Math.floor(Math.random() * subjects.length)];
      
      sessions.push({
        id: `session-${i}-${userData.email}`,
        date: sessionDate.toISOString(),
        duration: duration,
        subject: subject,
        notes: `Study session ${i + 1}`,
        rating: Math.floor(Math.random() * 5) + 1
      });
    }
    
    return sessions;
  };
  
  // Generate random tasks with some completed
  const generateTasks = () => {
    const tasks = [];
    const now = new Date();
    
    // Generate between 20-50 tasks
    const taskCount = Math.floor(Math.random() * 30) + 20;
    
    for (let i = 0; i < taskCount; i++) {
      // 60% of tasks are completed
      const completed = Math.random() < 0.6;
      
      // Random due date between yesterday and next 14 days
      const dueDate = new Date();
      dueDate.setDate(now.getDate() - 1 + Math.floor(Math.random() * 15));
      
      // Random completion date for completed tasks
      let completedAt = null;
      if (completed) {
        completedAt = new Date();
        completedAt.setDate(now.getDate() - Math.floor(Math.random() * 7));
      }
      
      // Random priority
      const priorities = ['low', 'medium', 'high'];
      const priority = priorities[Math.floor(Math.random() * priorities.length)];
      
      // Random categories
      const categories = ['Homework', 'Exam', 'Project', 'Reading', 'Research', 'Assignment'];
      const category = categories[Math.floor(Math.random() * categories.length)];
      
      tasks.push({
        id: `task-${i}-${userData.email}`,
        title: `Task ${i + 1} for ${category}`,
        description: `This is a ${priority} priority task for ${category}`,
        dueDate: dueDate.toISOString(),
        completed: completed,
        completedAt: completed ? completedAt.toISOString() : null,
        priority: priority,
        category: category
      });
    }
    
    return tasks;
  };
  
  // Calculate streak days (1-30)
  const streakDays = Math.floor(Math.random() * 30) + 1;
  
  // Create user object with generated data
  const user = {
    ...userData,
    studyData: generateStudySessions(),
    tasks: generateTasks(),
    streakDays: streakDays,
    gender: userData.gender || 'neutral',
    customAvatar: userData.customAvatar || null,
    major: userData.major || 'Student'
  };
  
  // Save to localStorage with unique key
  try {
    localStorage.setItem(`user_${userData.email}`, JSON.stringify(user));
    console.log(`Test user created: ${userData.email}`);
    return true;
  } catch (error) {
    console.error("Error saving test user:", error);
    return false;
  }
};

