// Avatar component for leaderboard
const LeaderboardAvatar = ({ seed, gender, customImage, size = 40 }) => {
  if (customImage) {
    return (
      <div className="rounded-full overflow-hidden" style={{ width: size, height: size }}>
        <img 
          src={customImage} 
          alt="User avatar" 
          className="w-full h-full object-cover"
        />
      </div>
    );
  }
  
  // Simple SVG avatar based on gender
  const bgColor = gender === 'male' ? '#4F46E5' : gender === 'female' ? '#EC4899' : '#10B981';
  const faceColor = gender === 'male' ? '#E5E7EB' : gender === 'female' ? '#FCE7F3' : '#D1FAE5';
  
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
      <circle cx="50" cy="50" r="50" fill={bgColor} />
      <circle cx="50" cy="50" r="35" fill={faceColor} />
      <circle cx="35" cy="45" r="5" fill="#1F2937" />
      <circle cx="65" cy="45" r="5" fill="#1F2937" />
      {gender === 'female' ? (
        <path d="M35,65 Q50,72 65,65" stroke="#1F2937" strokeWidth="3" fill="none" />
      ) : (
        <path d="M35,65 Q50,60 65,65" stroke="#1F2937" strokeWidth="3" fill="none" />
      )}
    </svg>
  );
};

// Single leaderboard entry component
const LeaderboardEntry = ({ user, rank, category, isCurrent }) => {
  const isTopThree = rank <= 3;
  // Different styling for top 3 vs other ranks
  const baseClasses = `rounded-lg p-4 mb-3 flex items-center justify-between relative overflow-hidden ${
    isCurrent ? 'border-2 border-neural-400' : ''
  }`;
  
  // Trophy icons based on rank
  const getTrophy = () => {
    if (rank === 1) return <GoldTrophy />;
    if (rank === 2) return <SilverTrophy />;
    if (rank === 3) return <BronzeTrophy />;
    return null;
  };
  
  // Special background for top 3
  const topThreeClasses = isTopThree 
    ? rank === 1 
      ? 'bg-gradient-to-r from-yellow-500/20 to-yellow-700/20 shadow-glow-gold' 
      : rank === 2 
        ? 'bg-gradient-to-r from-gray-400/20 to-gray-600/20 shadow-glow-silver' 
        : 'bg-gradient-to-r from-amber-700/20 to-amber-900/20 shadow-glow-bronze'
    : 'bg-neural-800/40';

  return (
    <motion.div 
      className={`${baseClasses} ${topThreeClasses}`}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, delay: rank * 0.05 }}
    >
      {/* Neural background for top 3 */}
      {isTopThree && (
        <div className="absolute inset-0 overflow-hidden opacity-20">
          <div 
            className="absolute inset-0 opacity-10"
            style={{ 
              backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
              backgroundSize: '20px 20px'
            }} 
          />
          {/* Animated neural nodes for top 3 only */}
          {Array.from({ length: 3 }).map((_, i) => (
            <motion.div
              key={i}
              className="absolute rounded-full bg-white/20"
              style={{
                width: 3 + Math.random() * 3,
                height: 3 + Math.random() * 3,
                top: `${10 + Math.random() * 80}%`,
                left: `${10 + Math.random() * 80}%`,
                filter: 'blur(1px)'
              }}
              animate={{ 
                opacity: [0.2, 0.5, 0.2] 
              }}
              transition={{
                duration: 3 + Math.random() * 2,
                repeat: Infinity,
                delay: Math.random() * 2
              }}
            />
          ))}
        </div>
      )}

      {/* Rank and user info */}
      <div className="flex items-center">
        <div className={`flex justify-center items-center ${isTopThree ? 'w-12' : 'w-8'} mr-4`}>
          {isTopThree ? (
            getTrophy()
          ) : (
            <span className="text-neural-300 font-semibold text-lg">{rank}</span>
          )}
        </div>
        
        <LeaderboardAvatar 
          seed={user.email} 
          gender={user.gender} 
          customImage={user.customAvatar} 
          size={isTopThree ? 48 : 40} 
        />
        
        <div className="ml-4">
          <div className={`font-bold ${isTopThree ? 'text-lg' : 'text-base'} text-white`}>
            {user.name}
          </div>
          {isTopThree && (
            <div className="text-neural-300 text-xs mt-1">
              {user.major ? `${user.major} Student` : 'Student'}
            </div>
          )}
        </div>
      </div>
      
      {/* Stats based on category */}
      <div className="text-right">
        <div className={`${isTopThree ? 'text-lg' : 'text-base'} font-bold text-neural-100`}>
          {category === 'study' 
            ? `${user.totalStudyHours.toFixed(1)} hrs` 
            : `${user.completedTasks} tasks`}
        </div>
        <div className="text-neural-400 text-xs mt-1">
          {category === 'study' 
            ? `${user.weeklyStudyHours.toFixed(1)} hrs this week` 
            : `${user.weeklyCompletedTasks} this week`}
        </div>
      </div>
      
      {/* Special indicator for current user */}
      {isCurrent && (
        <div className="absolute -left-1 top-0 bottom-0 w-1 bg-neural-400"></div>
      )}
    </motion.div>
  );
};

// Tab component for switching between categories
const LeaderboardTab = ({ active, category, label, icon, onClick }) => (
  <button
    className={`px-6 py-3 rounded-t-lg flex items-center space-x-2 transition-all ${
      active ? 'bg-neural-800 text-white' : 'bg-neural-900 text-neural-400 hover:text-neural-200'
    }`}
    onClick={() => onClick(category)}
  >
    <span className="text-xl">{icon}</span>
    <span>{label}</span>
  </button>
);

// Main Leaderboard component
const Leaderboard = () => {
  const { currentUser } = useAuth();
  const [category, setCategory] = useState('study'); // 'study' or 'tasks'
  const [leaderboardData, setLeaderboardData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentUserRank, setCurrentUserRank] = useState(null);
  
  // Load real user data from localStorage
  useEffect(() => {
    // Function to load all users from localStorage
    const loadAllUsers = () => {
      const allUsers = [];
      
      // Iterate through localStorage to find all user data
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        // Skip non-user data entries in localStorage
        if (!key.startsWith('user_') && key !== 'user') continue;
        
        try {
          const userData = JSON.parse(localStorage.getItem(key));
          // Skip invalid data
          if (!userData || !userData.email) continue;
          
          // Calculate total study hours from studyData array
          const totalStudyHours = userData.studyData 
            ? userData.studyData.reduce((total, session) => total + (session.duration || 0), 0) / 60 
            : 0;
          
          // Calculate completed tasks count
          const completedTasks = userData.tasks 
            ? userData.tasks.filter(task => task.completed).length 
            : 0;
          
          // Calculate weekly metrics (last 7 days)
          const weekStart = new Date();
          weekStart.setDate(weekStart.getDate() - 7);
          
          const weeklyStudyHours = userData.studyData
            ? userData.studyData
                .filter(session => new Date(session.date) >= weekStart)
                .reduce((total, session) => total + (session.duration || 0), 0) / 60
            : 0;
            
          const weeklyCompletedTasks = userData.tasks
            ? userData.tasks
                .filter(task => task.completed && new Date(task.completedAt) >= weekStart)
                .length
            : 0;
          
          // Add processed user to the list
          allUsers.push({
            id: userData.id || userData.email,
            name: userData.name || userData.email.split('@')[0],
            email: userData.email,
            gender: userData.gender || 'neutral',
            customAvatar: userData.customAvatar || null,
            major: userData.major || userData.studyField || null,
            totalStudyHours: totalStudyHours,
            weeklyStudyHours: weeklyStudyHours,
            completedTasks: completedTasks,
            weeklyCompletedTasks: weeklyCompletedTasks,
            streakDays: userData.streakDays || 0,
            isCurrentUser: currentUser && userData.email === currentUser.email
          });
        } catch (error) {
          console.error(`Error processing user data for key ${key}:`, error);
        }
      }
      
      // If no users found or current user not in list, ensure current user is included
      if (currentUser && !allUsers.find(u => u.email === currentUser.email)) {
        // Calculate current user stats
        const totalStudyHours = currentUser.studyData 
          ? currentUser.studyData.reduce((total, session) => total + (session.duration || 0), 0) / 60 
          : 0;
        
        const completedTasks = currentUser.tasks 
          ? currentUser.tasks.filter(task => task.completed).length 
          : 0;
        
        // Calculate weekly metrics for current user
        const weekStart = new Date();
        weekStart.setDate(weekStart.getDate() - 7);
        
        const weeklyStudyHours = currentUser.studyData
          ? currentUser.studyData
              .filter(session => new Date(session.date) >= weekStart)
              .reduce((total, session) => total + (session.duration || 0), 0) / 60
          : 0;
          
        const weeklyCompletedTasks = currentUser.tasks
          ? currentUser.tasks
              .filter(task => task.completed && new Date(task.completedAt) >= weekStart)
              .length
          : 0;
        
        // Add current user to the list
        allUsers.push({
          id: currentUser.id || currentUser.email,
          name: currentUser.name || currentUser.email.split('@')[0],
          email: currentUser.email,
          gender: currentUser.gender || 'neutral',
          customAvatar: currentUser.customAvatar || null,
          major: currentUser.major || currentUser.studyField || null,
          totalStudyHours: totalStudyHours,
          weeklyStudyHours: weeklyStudyHours,
          completedTasks: completedTasks,
          weeklyCompletedTasks: weeklyCompletedTasks,
          streakDays: currentUser.streakDays || 0,
          isCurrentUser: true
        });
      }
      
      // If no other users, add some demo users with realistic stats
      if (allUsers.length < 3) {
        const demoUsers = [
          {
            id: 'user-demo-1',
            name: 'Alex Rivera',
            email: 'alex.rivera@example.com',
            gender: 'male',
            customAvatar: null,
            major: 'Computer Science',
            totalStudyHours: 112.5,
            weeklyStudyHours: 18.2,
            completedTasks: 47,
            weeklyCompletedTasks: 12,
            streakDays: 15,
            isCurrentUser: false
          },
          {
            id: 'user-demo-2',
            name: 'Samantha Chen',
            email: 'samchen@example.com',
            gender: 'female',
            customAvatar: null,
            major: 'Physics',
            totalStudyHours: 98.3,
            weeklyStudyHours: 16.5,
            completedTasks: 42,
            weeklyCompletedTasks: 9,
            streakDays: 12,
            isCurrentUser: false
          },
          {
            id: 'user-demo-3',
            name: 'Jordan Taylor',
            email: 'jordan23@example.com',
            gender: 'neutral',
            customAvatar: null,
            major: 'Mathematics',
            totalStudyHours: 78.6,
            weeklyStudyHours: 14.8,
            completedTasks: 35,
            weeklyCompletedTasks: 8,
            streakDays: 9,
            isCurrentUser: false
          }
        ];
        
        // Only add demo users needed to have at least 3 total
        for (let i = 0; i < Math.min(demoUsers.length, 3 - allUsers.length); i++) {
          allUsers.push(demoUsers[i]);
        }
      }
      
      return allUsers;
    };
    
    // Load all users and sort based on category
    const allUsers = loadAllUsers();
    
    // Sort based on the category (study hours or completed tasks)
    const sortedData = [...allUsers].sort((a, b) => {
      if (category === 'study') {
        return b.totalStudyHours - a.totalStudyHours;
      } else {
        return b.completedTasks - a.completedTasks;
      }
    });
    
    // Find current user's rank if they exist
    if (currentUser) {
      const currentUserIndex = sortedData.findIndex(user => user.isCurrentUser);
      if (currentUserIndex !== -1) {
        setCurrentUserRank(currentUserIndex + 1);
      }
    }
    
    setLeaderboardData(sortedData);
    setLoading(false);
  }, [category, currentUser]);
  
  // Loading state
  if (loading) {
    return (
      <NeuralPageWrapper title="Leaderboard">
        <div className="flex justify-center items-center h-64">
          <div className="text-white flex flex-col items-center">
            <div className="w-12 h-12 border-4 border-t-transparent border-blue-500 rounded-full animate-spin mb-4" />
            Loading leaderboard data...
          </div>
        </div>
      </NeuralPageWrapper>
    );
  }
  
  // Handle empty data scenario
  if (leaderboardData.length === 0) {
    return (
      <NeuralPageWrapper title="Leaderboard">
        <div className="max-w-4xl mx-auto p-4 text-center">
          <h1 className="text-3xl font-bold text-white mb-3">
            Neural Network Champions
          </h1>
          <div className="bg-neural-800 rounded-lg p-8 mt-8 shadow-xl">
            <div className="text-neural-300 text-xl mb-4">
              No study data available yet
            </div>
            <p className="text-neural-400">
              Start tracking your studies to see your position on the leaderboard!
            </p>
          </div>
        </div>
      </NeuralPageWrapper>
    );
  }
  
  return (
    <NeuralPageWrapper title="Leaderboard">
      <div className="max-w-4xl mx-auto p-4">
        {/* Page header */}
        <div className="text-center mb-8">
          <motion.h1 
            className="text-3xl font-bold text-white mb-3"
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            Neural Network Champions
          </motion.h1>
          <motion.p 
            className="text-neural-300"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5, delay: 0.2 }}
          >
            Celebrate the dedicated minds powering their knowledge journey!
          </motion.p>
        </div>
        
        {/* Top 3 podium - special highlight section */}
        <div className="mb-10">
          <motion.h2 
            className="text-xl font-semibold text-neural-200 mb-4"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.4 }}
          >
            🏆 Top Achievers
          </motion.h2>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* We map the top 3 users from our sorted data */}
            {leaderboardData.slice(0, 3).map((user, idx) => {
              const rank = idx + 1;
              const isCurrent = user.isCurrentUser;
              
              // Calculate card height - 1st place is tallest
              const heights = ['md:h-64', 'h-56', 'h-56'];
              const delay = [0.1, 0.2, 0.3];
              
              // Special podium positions - 1st in middle, 2nd on left, 3rd on right for desktop
              const order = ['md:order-2', 'md:order-1', 'md:order-3'];
              const marginTop = ['md:mt-0', 'md:mt-6', 'md:mt-6'];
              
              return (
                <motion.div 
                  key={user.id}
                  className={`relative ${heights[idx]} ${order[idx]} ${marginTop[idx]}`}
                  initial={{ opacity: 0, y: 30 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.5, delay: delay[idx] }}
                >
                  {/* Trophy number indicator */}
                  <div className="absolute -top-5 left-1/2 transform -translate-x-1/2 bg-neural-700 rounded-full w-10 h-10 flex items-center justify-center border-2 border-neural-600 z-10">
                    {rank === 1 ? (
                      <span className="text-yellow-500 text-xl font-bold">1</span>
                    ) : rank === 2 ? (
                      <span className="text-gray-300 text-xl font-bold">2</span>
                    ) : (
                      <span className="text-amber-700 text-xl font-bold">3</span>
                    )}
                  </div>
                  
                  {/* Podium card */}
                  <div className={`
                    h-full rounded-lg p-6 flex flex-col items-center justify-between
                    ${rank === 1 
                      ? 'bg-gradient-to-b from-yellow-900/30 to-yellow-700/10 border border-yellow-600/30 shadow-glow-gold' 
                      : rank === 2 
                        ? 'bg-gradient-to-b from-gray-800/30 to-gray-600/10 border border-gray-500/30 shadow-glow-silver' 
                        : 'bg-gradient-to-b from-amber-900/30 to-amber-800/10 border border-amber-700/30 shadow-glow-bronze'}
                    ${isCurrent ? 'border-2 border-neural-400' : ''}
                  `}>
                    
                    {/* Neural background effect for top 3 */}
                    <div className="absolute inset-0 overflow-hidden rounded-lg">
                      <div 
                        className="absolute inset-0 opacity-10"
                        style={{ 
                          backgroundImage: `linear-gradient(to right, rgba(100, 200, 255, 0.15) 1px, transparent 1px),
                                          linear-gradient(to bottom, rgba(100, 200, 255, 0.15) 1px, transparent 1px)`,
                          backgroundSize: '20px 20px'
                        }} 
                      />
                      
                      {/* Animated nodes */}
                      {Array.from({ length: 6 }).map((_, i) => (
                        <motion.div
                          key={i}
                          className="absolute rounded-full bg-white/20"
                          style={{
                            width: 3 + Math.random() * 4,
                            height: 3 + Math.random() * 4,
                            top: `${10 + Math.random() * 80}%`,
                            left: `${10 + Math.random() * 80}%`,
                            filter: 'blur(1px)'
                          }}
                          animate={{ 
                            opacity: [0.2, 0.5, 0.2] 
                          }}
                          transition={{
                            duration: 3 + Math.random() * 2,
                            repeat: Infinity,
                            delay: Math.random() * 2
                          }}
                        />
                      ))}
                    </div>
                    
                    {/* Trophy icon */}
                    <div className="mb-2 relative z-10">
                      {rank === 1 ? (
                        <GoldTrophy />
                      ) : rank === 2 ? (
                        <SilverTrophy />
                      ) : (
                        <BronzeTrophy />
                      )}
                    </div>
                    
                    {/* User avatar - larger for top 3 */}
                    <div className="mb-3 relative z-10">
                      <LeaderboardAvatar 
                        seed={user.email} 
                        gender={user.gender} 
                        customImage={user.customAvatar} 
                        size={rank === 1 ? 80 : 64}
                      />
                    </div>
                    
                    {/* User info */}
                    <div className="text-center relative z-10">
                      <div className={`font-bold ${rank === 1 ? 'text-xl mb-1' : 'text-lg'} text-white`}>
                        {user.name}
                      </div>
                      <div className="text-neural-300 text-sm mb-3">
                        {user.major ? `${user.major} Student` : 'Student'}
                      </div>
                      
                      {/* User stats based on category */}
                      <div className="bg-neural-900/50 px-4 py-2 rounded-lg">
                        <div className="text-lg font-bold text-neural-100">
                          {category === 'study' 
                            ? `${user.totalStudyHours.toFixed(1)} hrs` 
                            : `${user.completedTasks} tasks`}
                        </div>
                        <div className="text-neural-400 text-xs mt-1">
                          {rank === 1 ? '👑 Champion' : rank === 2 ? '🥈 Runner-up' : '🥉 Impressive!'}
                        </div>
                      </div>
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </div>
        </div>
        
        {/* Category tabs */}
        <div className="mb-6 flex">
          <LeaderboardTab 
            active={category === 'study'} 
            category="study" 
            label="Study Hours" 
            icon="⏱️" 
            onClick={setCategory} 
          />
          <LeaderboardTab 
            active={category === 'tasks'} 
            category="tasks" 
            label="Completed Tasks" 
            icon="✅" 
            onClick={setCategory} 
          />
        </div>
        
        {/* Leaderboard entries - positions 1 through 15 */}
        <div className="bg-neural-800 rounded-lg p-6 shadow-xl">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-semibold text-white">
              {category === 'study' ? 'Study Time Leaders' : 'Task Completion Leaders'}
            </h2>
            
            {currentUserRank && currentUserRank > 15 && (
              <div className="text-neural-300 text-sm">
                Your rank: <span className="text-neural-100 font-semibold">{currentUserRank}</span>
              </div>
            )}
          </div>
          
          <div className="space-y-1">
            {leaderboardData.slice(0, 15).map((user, idx) => (
              <LeaderboardEntry 
                key={user.id} 
                user={user} 
                rank={idx + 1} 
                category={category}
                isCurrent={user.isCurrentUser}
              />
            ))}
          </div>
          
          {/* Motivational message */}
          <motion.div 
            className="mt-8 text-center text-neural-300 text-sm bg-neural-700/30 rounded-lg p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1 }}
          >
            <p className="mb-2">🚀 <span className="text-white">Every study session counts!</span> Keep pushing your limits.</p>
            <p>Challenge yourself daily to climb the leaderboard and unlock your full potential.</p>
          </motion.div>
        </div>
      </div>
      
      {/* Admin panel for demonstration purposes */}
      <div className="mt-10 mb-5 border border-neural-800 rounded-lg p-4 bg-neural-900/50">
        <div className="flex justify-between items-center mb-3">
          <h3 className="text-sm text-neural-400">Admin Panel</h3>
          <span className="text-xs text-neural-500">For demonstration only</span>
        </div>
        <div className="flex space-x-3">
          <button
            onClick={() => {
              const count = populateLeaderboard();
              alert(`Generated ${count} test users with real study data`);
              // Reload to reflect changes
              window.location.reload();
            }}
            className="bg-neural-700 hover:bg-neural-600 text-white text-sm py-1 px-3 rounded-md transition-colors"
          >
            Generate Test Data
          </button>
          <button
            onClick={() => {
              const count = clearTestUsers();
              alert(`Cleared ${count} test users`);
              // Reload to reflect changes
              window.location.reload();
            }}
            className="bg-red-800/50 hover:bg-red-700/60 text-white text-sm py-1 px-3 rounded-md transition-colors"
          >
            Clear Test Data
          </button>
        </div>
      </div>
    </NeuralPageWrapper>
  );
};

export default Leaderboard; 